<div class="container py-4"><div class="mb-4"><div class="text-muted small"><?= e($client['company_name']) ?></div><h1 class="h3"><?= e($title) ?></h1></div><form method="post" action="<?= $assessment?'assessments/update':'assessments/store' ?>" class="card border-0 shadow-sm"><div class="card-body"><input type="hidden" name="client_id" value="<?= (int)$client['id'] ?>"><?php if($assessment): ?><input type="hidden" name="id" value="<?= (int)$assessment['id'] ?>"><?php endif; ?><?php include __DIR__.'/../partials/csrf.php'; ?><div class="row g-3"><div class="col-md-8"><label class="form-label">Assessment name *</label><input required name="name" class="form-control" value="<?= e($assessment['name']??'') ?>"></div><div class="col-md-4"><label class="form-label">Status</label><select name="status" class="form-select"><?php foreach(['draft','in_progress','completed','approved'] as $s): ?><option value="<?= $s ?>" <?= (($assessment['status']??'draft')===$s)?'selected':'' ?>><?= ucwords(str_replace('_',' ',$s)) ?></option><?php endforeach; ?></select></div><div class="col-12"><label class="form-label">Scope</label><textarea name="scope" class="form-control" rows="3"><?= e($assessment['scope']??'') ?></textarea></div><div class="col-md-8"><label class="form-label">Methodology</label><textarea name="methodology" class="form-control" rows="3"><?= e($assessment['methodology']??'') ?></textarea></div><div class="col-md-4"><label class="form-label">Risk score (0–100)</label><input type="number" min="0" max="100" name="risk_score" class="form-control" value="<?= (int)($assessment['risk_score']??0) ?>"></div></div></div><div class="card-footer bg-white d-flex justify-content-between"><a class="btn btn-outline-secondary" href="assessments?client_id=<?= (int)$client['id'] ?>">Cancel</a><button class="btn btn-primary">Save assessment</button></div></form></div>
